"""Generated isolated Scope selection. Identity is supplied by the native hook.

This does not authenticate delegation, mint capture/ref/admission, or bypass an
engine's guard. Non-target sessions execute the exact previous source.
"""

from integrity_client_memory.configuration import value as _integrity_value, require_config as _integrity_require_config
import base64
import hashlib
import io
import json
import sys
import stat
from contextlib import nullcontext
from pathlib import Path

TARGET_SESSION = None
LEGACY_SHA = '0be476a72345a9e20a58a0f7083b5af0ac4910a00ba755c43d3a9faa506f747d'
SUCCESSOR_SHA = 'ec5e71fd52551a711a502eb5438173add46e3c04a645e83f9e30c7eb2fc5e7de'
LEGACY_SOURCE = base64.b64decode('')
SUCCESSOR_SOURCE = base64.b64decode('')


def select_source(argv, raw):
    session = None
    if argv[:1] == ["status"]:
        # Selection is read-only; the selected engine still validates all args.
        if argv.count("--session") == 1:
            at = argv.index("--session")
            if at + 1 < len(argv):
                session = argv[at + 1]
    else:
        try:
            payload = json.loads(raw.decode("utf-8")) if raw.strip() else {}
            if isinstance(payload, dict):
                session = (payload.get("session_id") or payload.get("sessionId")
                           or payload.get("thread_id"))
                if isinstance(session, str):
                    session = session.strip()
        except (UnicodeDecodeError, ValueError):
            pass
    if TARGET_SESSION is not None and session == TARGET_SESSION:
        return SUCCESSOR_SOURCE, SUCCESSOR_SHA
    return LEGACY_SOURCE, LEGACY_SHA



def _require_plain_directory(path):
    try:
        info = path.lstat()
    except FileNotFoundError:
        return
    if (stat.S_ISLNK(info.st_mode) or not stat.S_ISDIR(info.st_mode)
            or getattr(info, "st_file_attributes", 0) & 0x400):
        raise ValueError("scope_canary_namespace_link_or_non_directory")


def isolated_state_root(base, *, check=True):
    # Legacy pruning visits only immediate *.json-shaped entries via iterdir.
    # Never copy or relabel the previous shared state as isolated state.
    root = Path(base).resolve()
    for name in ("scope-canary-v4", hashlib.sha256(TARGET_SESSION.encode()).hexdigest()[:32]):
        root = root / name
        if check:
            _require_plain_directory(root)
    return root


class _AlreadyLockedStore:
    """The original handler runs under the one existing outer session lock."""

    def __init__(self, store):
        self.store = store

    def __getattr__(self, name):
        return getattr(self.store, name)

    def locked(self, session):
        return nullcontext()


def configure_target_namespace(namespace):
    original_root = namespace["state_root"]
    original_handle = namespace["handle"]
    original_store = namespace["Store"]
    namespace["state_root"] = lambda harness, configured=None: isolated_state_root(
        original_root(harness, configured), check=False)

    class Store(original_store):
        def check_namespace(self):
            _require_plain_directory(self.root.parent)
            _require_plain_directory(self.root)

        def load(self, session):
            self.check_namespace()
            return super().load(session)

        def locked(self, session):
            self.check_namespace()
            return super().locked(session)

    namespace["Store"] = Store

    def handle(event, payload, store):
        session = namespace["session_key"](payload)
        if session != TARGET_SESSION:
            raise namespace["SynapseError"]("scope_canary_target_identity_mismatch")
        # The immutable recovery allowlist stays available without a writable
        # state directory. No shell, mutation, or new tool is added to it.
        if event == "PreToolUse" and namespace["recovery_tool"](payload):
            return None
        with store.locked(session):
            state = store.load(session)
            if state is not None:
                namespace["ensure_scope_schema"](state)
            if state is None or not state.get("instructions"):
                reason = ("INTEGRITY SCOPE CANARY isolated target has no complete owner task. "
                          "Effects remain blocked. Supply a genuine full owner UI input with "
                          "INTEGRITY_SCOPE_REPLACE on its own first line; no shared state was migrated.")
                if event == "UserPromptSubmit":
                    prompt = namespace["prompt_text"](payload)
                    marker = namespace["OWNER_TRANSITION_RE"].fullmatch(prompt)
                    if (namespace["question_reply_answers"](prompt) is not None
                            or marker is None or marker.group(1) != "REPLACE"
                            or not marker.group(2).strip()):
                        return {"continue": False, "stopReason": reason, "systemMessage": reason}
                elif event == "PreToolUse":
                    return namespace["deny_output"](reason)
                elif event == "SessionStart":
                    return namespace["context_output"](event, reason)
                else:
                    # A compact notification alone cannot create an empty
                    # scope file that would later authorize target effects.
                    return None
            return original_handle(event, payload, _AlreadyLockedStore(store))

    namespace["handle"] = handle



GOAL_SHA = '4fd5625418d9db04ac67481a09c6ef6020abb16848ade86e63528c5209bea115'
GOAL_SOURCE = ''
CYCLE_SHA = 'fd8ef4163c9d373d28a2df23b0db9a676f37276ab88de0f3f77c2ed490f447c3'
CYCLE_SOURCE = base64.b64decode('')
NATIVE_CYCLE_SHA = '08aaef5998f502fdc60cd559e2125f6e7ea2ac073beef996171dc7495b4379d1'
NATIVE_CYCLE_SOURCE = base64.b64decode('')

def native_cycle_harness(argv):
    import argparse
    parser=argparse.ArgumentParser(add_help=False)
    parser.add_argument('--harness',choices=('codex','claude'))
    args,_=parser.parse_known_args(argv)
    return args.harness=='codex'

def configure_complete_scope(namespace):
    import types
    raw = base64.b64decode(GOAL_SOURCE)
    if hashlib.sha256(raw).hexdigest() != GOAL_SHA:
        raise RuntimeError('complete_scope_source_digest_mismatch')
    module = types.ModuleType('_integrity_complete_scope')
    module.__file__ = __file__
    exec(compile(raw, __file__, 'exec'), module.__dict__)
    module.install(namespace)

CHILD_GUARD_SOURCE=''
CHILD_GUARD_SHA='7e2fb45f9fda49ae9de65c0e5050648ef4e744603d7684075bdfe6e3ccb95464'

def configure_native_cycles(namespace):
    import types
    plain_legacy_handle = namespace['handle']
    for raw,pin in ((CYCLE_SOURCE,CYCLE_SHA),(NATIVE_CYCLE_SOURCE,NATIVE_CYCLE_SHA)):
        if hashlib.sha256(raw).hexdigest()!=pin:
            raise RuntimeError('scope_native_cycle_source_digest_mismatch')
    neutral=types.ModuleType('_integrity_native_scope_cycle')
    neutral.__file__=__file__
    exec(compile(CYCLE_SOURCE,__file__,'exec'),neutral.__dict__)
    sys.modules[neutral.__name__]=neutral
    adapter=types.ModuleType('_integrity_native_scope_adapter')
    adapter.__file__=__file__
    exec(compile(NATIVE_CYCLE_SOURCE,__file__,'exec'),adapter.__dict__)
    legacy=types.SimpleNamespace(**namespace)
    namespace['handle']=lambda event,payload,store:adapter.handle(event,payload,store,legacy)
    namespace['readonly_memory_terminal']=adapter.readonly_memory_terminal
    configure_complete_scope(namespace)
    child_raw = base64.b64decode(CHILD_GUARD_SOURCE)
    if hashlib.sha256(child_raw).hexdigest() != CHILD_GUARD_SHA:
        raise RuntimeError('scope_child_guard_source_digest_mismatch')
    child = types.ModuleType('_integrity_scope_child_guard')
    child.__file__ = __file__
    exec(compile(child_raw, __file__, 'exec'), child.__dict__)
    child.install(namespace, plain_legacy_handle)

def main(argv=None):
    if sys.platform != "win32":
        raise RuntimeError("windows_native_scope_requires_windows")
    argv = sys.argv[1:] if argv is None else argv
    raw = b'' if argv[:1] == ['status'] else sys.stdin.buffer.read()
    source, digest = select_source(argv, raw)
    if hashlib.sha256(source).hexdigest() != digest:
        raise RuntimeError('scope_selected_source_digest_mismatch')
    original_stdin = sys.stdin
    replay = None
    try:
        if argv[:1] != ['status']:
            replay = io.TextIOWrapper(io.BytesIO(raw), encoding='utf-8')
            sys.stdin = replay
        namespace = {'__name__': '_integrity_scope_selected', '__file__': __file__}
        exec(compile(source, __file__, 'exec'), namespace)
        if digest == SUCCESSOR_SHA:
            configure_target_namespace(namespace)
        elif digest == LEGACY_SHA and native_cycle_harness(argv):
            configure_native_cycles(namespace)
        return namespace['main'](argv)
    finally:
        sys.stdin = original_stdin
        if replay is not None:
            replay.close()


if __name__ == "__main__":
    _integrity_require_config()

if __name__ == "__main__":
    sys.exit(main())
